-- Park boundary polygons for the /parks content feature.
-- State parks: Oregon State Parks FeatureServer (Oregon GEO / OPRD). City parks: OpenStreetMap.
-- All geometries WGS84 (SRID 4326), stored as MultiPolygon to match the boundaries convention.
-- Verified + cited per CLAUDE.md section 0. Polygons are never approximated.
-- Applied to hosted Supabase 2026-06-03 (ryan-realty-platform).

-- 1. Allow geo_type='park' in the boundaries CHECK constraint.
ALTER TABLE public.boundaries DROP CONSTRAINT IF EXISTS boundaries_geo_type_check;
ALTER TABLE public.boundaries ADD CONSTRAINT boundaries_geo_type_check
  CHECK (geo_type = ANY (ARRAY['city'::text, 'neighborhood'::text, 'subdivision'::text, 'park'::text]));

-- 2. Replace the park rows (idempotent).
DELETE FROM public.boundaries WHERE geo_type = 'park';



















